class Vm { var count = 0 }
class Store { val map = mutableMapOf<String, Vm>() }
fun obtain(store: Store) = store.map.getOrPut("main") { Vm() }

fun main() {
    val store = Store()
    obtain(store).count++
    // rotation: Activity recreated, store retained
    obtain(store).count++
    val afterRotation = obtain(store).count
    // process death: a fresh process starts with a new store
    val afterDeath = obtain(Store()).count
    println("$afterRotation $afterDeath")
}

