class Handle(private val saved: MutableMap<String, String>) {
    operator fun get(key: String): String? = saved[key]
    operator fun set(key: String, value: String) { saved[key] = value }
}

class FormVm(private val handle: Handle) {
    var nameInMemory = ""
    var nameSaved: String
        get() = handle["name"] ?: ""
        set(v) { handle["name"] = v }
}

fun main() {
    val persisted = mutableMapOf<String, String>()
    val vm1 = FormVm(Handle(persisted))
    vm1.nameInMemory = "Ann"
    vm1.nameSaved = "Ann"
    // process death: a new ViewModel is restored from the persisted map
    val vm2 = FormVm(Handle(persisted.toMutableMap()))
    println("[${vm2.nameInMemory}] [${vm2.nameSaved}]")
}

